import {portrait} from './companions.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function progressTransferPanel(transfer,persist){
 const p=transfer.candidate;
 return `<section class="panel progress-transfer" aria-labelledby="progress-transfer-title"><h2 id="progress-transfer-title">Bring progress from another site</h2><ol><li>On the old site, use the browser and device where you played. Open Grown-up notes, switch to the explorer you want, and choose <strong>Download our notes</strong>.</li><li>Save that JSON file in Files or Downloads. Choose it below on this site.</li><li>Check the preview, then add it as a separate explorer. Repeat for any other explorers.</li></ol><p><a href="https://number-garden-together.tastypeach3.chatgpt.site/#notes" target="_blank" rel="noopener">Earlier Number Garden site <span aria-hidden="true">↗</span></a></p><p>Existing explorers here stay as they are. Keep your old notebook and downloaded file until you have checked the new explorer. Use one tab here while importing. These files contain private progress: do not post them in public.</p><label class="import-file-label" for="progress-file">Choose a downloaded notes file</label><input id="progress-file" type="file" accept=".json,application/json" ${transfer.reading?'disabled':''} aria-describedby="progress-file-help"><p class="tiny" id="progress-file-help">JSON, up to 5 MB. Read only on this device; the file is not uploaded. This moves one explorer, rather than combining notebooks.</p>${!persist?'<p class="storage-warning">Remember progress is off. An imported explorer will last only for this session unless you turn saving on. Keep your file.</p>':''}<p id="progress-import-status" role="status" tabindex="-1">${transfer.reading?'Reading the file on this device…':esc(transfer.message)}</p>${p?`<div class="import-preview"><h3 id="progress-import-preview" tabindex="-1">Notebook ready to bring over</h3><p class="explorer-preview">${portrait(p.choice.avatar,true)} ${esc(p.choice.color)} ${esc(p.choice.symbol)} (a free combination will be used)</p><p>${p.summary.tasks} original multiplication task records. ${p.summary.destinations.length?`Saved destinations: ${p.summary.destinations.map(esc).join(', ')}.`:'This is an earlier notebook; new destinations start fresh.'}</p><p>We’ll add a separate explorer and use a free picture/color/symbol combination. The original file is kept as a downloadable recovery copy. Unavailable questions may close under this version’s normal restore rules.</p><div class="summary-links"><button class="primary" id="progress-import-confirm">Add as a separate explorer</button><button class="secondary" id="progress-import-cancel">Cancel</button></div></div>`:''}</section>`;
}
